import {useState} from 'react';
import {Alert, Box, Button, Checkbox, Dialog, DialogActions, DialogContent, DialogTitle, FormControlLabel, IconButton, MenuItem, Stack, TextField, Typography} from '@mui/material';
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import {communicationStyles, customerPhoneKey, ICustomerDetail, SaveCustomerInput} from '../../models/customer';
import {useSaveCustomerMutation} from '../orders/createOrder/createOrderApi';
import {getApiErrorMessage} from '../../api/errors';

type Props = {customer?: ICustomerDetail; onClose: () => void; onSaved: (customer: ICustomerDetail) => void};
export default function CustomerEditDialog({customer, onClose, onSaved}: Props) {
    const [form, setForm] = useState<SaveCustomerInput>(() => ({name: customer?.name || '', address: customer?.address || '',
        phones: customer?.phones?.length ? [...customer.phones].sort((a, b) => Number(customerPhoneKey(a.phone) !== customerPhoneKey(customer.phone)) - Number(customerPhoneKey(b.phone) !== customerPhoneKey(customer.phone))) : [{phone: customer?.phone || '', label: ''}],
        email: customer?.email || '', taxNumber: customer?.taxNumber || '', contract: customer?.contract || '',
        communicationStyle: customer?.communicationStyle || 'unknown', attentionRequired: customer?.attentionRequired || false,
        summary: customer?.summary || '', version: customer?.version || 0}));
    const [save, state] = useSaveCustomerMutation(); const [error, setError] = useState('');
    const field = (name: keyof SaveCustomerInput, value: unknown) => setForm(current => ({...current, [name]: value}));
    const validPhones = form.phones.every(p => /^[+0-9\s()-]+$/.test(p.phone) && customerPhoneKey(p.phone).length >= 7 && customerPhoneKey(p.phone).length <= 20);
    const duplicates = new Set(form.phones.map(p => customerPhoneKey(p.phone))).size !== form.phones.length;
    async function submit() {
        setError('');
        try {onSaved(await save({...form, id: customer?.id}).unwrap());}
        catch (failure) {setError(getApiErrorMessage(failure, 'Не удалось сохранить карточку клиента.'));}
    }
    return <Dialog open onClose={state.isLoading ? undefined : onClose} fullWidth maxWidth="md">
        <Box component="form" onSubmit={event => {event.preventDefault(); void submit();}}>
            <DialogTitle>{customer ? 'Редактирование клиента' : 'Новый клиент'}</DialogTitle>
            <DialogContent><Stack spacing={2} pt={1}>
                {error && <Alert severity="error">{error}</Alert>}
                <TextField required label="Ф.И.О. клиента" value={form.name} inputProps={{minLength: 2, maxLength: 200}} onChange={event => field('name', event.target.value)}/>
                <Typography fontWeight={700}>Телефоны</Typography>
                <Typography variant="body2" color="text.secondary">Первый номер — основной. Общий семейный или рабочий телефон можно указать у нескольких клиентов.</Typography>
                {form.phones.map((phone, index) => <Stack key={index} direction={{xs: 'column', sm: 'row'}} gap={1}>
                    <TextField required fullWidth label={index === 0 ? 'Основной телефон' : `Телефон ${index + 1}`} value={phone.phone} inputProps={{maxLength: 64}}
                        onChange={event => field('phones', form.phones.map((p, i) => i === index ? {...p, phone: event.target.value} : p))}/>
                    <TextField fullWidth label="Подпись к номеру" placeholder="Личный, рабочий, супруг…" value={phone.label} inputProps={{maxLength: 80}}
                        onChange={event => field('phones', form.phones.map((p, i) => i === index ? {...p, label: event.target.value} : p))}/>
                    <IconButton disabled={form.phones.length === 1} aria-label={`Удалить телефон ${index + 1}`} onClick={() => field('phones', form.phones.filter((_, i) => i !== index))}><DeleteOutlineIcon/></IconButton>
                </Stack>)}
                {duplicates && <Alert severity="warning">Один номер указан несколько раз.</Alert>}
                <Button sx={{alignSelf: 'flex-start'}} disabled={form.phones.length >= 20} onClick={() => field('phones', [...form.phones, {phone: '', label: ''}])}>Добавить телефон</Button>
                <TextField label="Основной адрес" value={form.address} inputProps={{maxLength: 1000}} onChange={event => field('address', event.target.value)}/>
                <Stack direction={{xs: 'column', sm: 'row'}} gap={2}>
                    <TextField fullWidth type="email" label="Email" value={form.email} inputProps={{maxLength: 320}} onChange={event => field('email', event.target.value)}/>
                    <TextField fullWidth label="УНП / реквизиты" value={form.taxNumber} inputProps={{maxLength: 64}} onChange={event => field('taxNumber', event.target.value)}/>
                </Stack>
                <TextField label="Договор" value={form.contract} inputProps={{maxLength: 256}} onChange={event => field('contract', event.target.value)}/>
                <TextField select label="Стиль общения" value={form.communicationStyle} onChange={event => field('communicationStyle', event.target.value)}>
                    {Object.entries(communicationStyles).map(([value, label]) => <MenuItem key={value} value={value}>{label}</MenuItem>)}
                </TextField>
                <FormControlLabel control={<Checkbox checked={form.attentionRequired} onChange={event => field('attentionRequired', event.target.checked)}/>} label="Требует внимания менеджера"/>
                <TextField label="Памятка для команды" multiline minRows={3} value={form.summary} inputProps={{maxLength: 4000}} helperText="Предпочтения, удобное время звонка, важные договорённости. Подробные ситуации добавляйте в журнал."
                    onChange={event => field('summary', event.target.value)}/>
            </Stack></DialogContent>
            <DialogActions><Button disabled={state.isLoading} onClick={onClose}>Отмена</Button><Button type="submit" variant="contained" disabled={state.isLoading || form.name.trim().length < 2 || !validPhones || duplicates}>{state.isLoading ? 'Сохраняем…' : 'Сохранить клиента'}</Button></DialogActions>
        </Box>
    </Dialog>;
}
