export interface ICustomer {
  organization?: import('../components/counterparties/counterpartiesApi').CompanyIdentity | null;
  id?: number | null;
  name: string;
  address: string;
  phone: string;
}

export interface ICustomerCard extends ICustomer {
  id: number; orderCount: number; lastOrderAt: string | null; totalAmount: number;
  phones?: ICustomerPhone[]; communicationStyle?: string; attentionRequired?: boolean; summary?: string; openIncidentCount?: number;
}
export interface ICustomerPage {items: ICustomerCard[]; total: number; page: number; pageSize: number}
export interface ICustomerDetail extends ICustomer {
  id: number; orderCount: number; addresses: string[];
  orders: ICustomerOrder[]; phones: ICustomerPhone[]; email: string; taxNumber: string; contract: string;
  communicationStyle: string; attentionRequired: boolean; summary: string; version: number;
  totalAmount: number; firstOrderAt: string | null; lastOrderAt: string | null; openIncidentCount: number;
}
export interface ICustomerPhone {phone: string; label: string}
export interface ICustomerOrder {id: number; createdDate: string; finalSum: number; status: string; name: string; address: string; phone: string; comment?: string}
export interface ICustomerOrdersPage {items: ICustomerOrder[]; total: number; page: number; pageSize: number}
export interface ICustomerNote {id: number; kind: string; text: string; authorUserId: number; authorName: string; createdAt: string; orderId: number | null; isResolved: boolean; resolvedAt: string | null}
export interface ICustomerNotesPage {items: ICustomerNote[]; total: number; page: number; pageSize: number}
export interface SaveCustomerInput {name: string; address: string; phones: ICustomerPhone[]; email: string; taxNumber: string; contract: string; communicationStyle: string; attentionRequired: boolean; summary: string; version: number}
export interface AddCustomerNoteInput {customerId: number; requestId: string; text: string; kind: string; orderId?: number | null}
export const communicationStyles: Record<string, string> = {unknown: 'Не указан', patient: 'Терпеливый, спокойный', impatient: 'Нетерпеливый, нужен быстрый ответ'};
export const customerPhoneKey = (phone: string) => {
  const digits = phone.replace(/[^0-9]/g, '');
  if (digits.startsWith('00')) return digits.slice(2);
  if (digits.length === 11 && digits.startsWith('80')) return '375' + digits.slice(2);
  if (digits.length === 11 && digits.startsWith('8')) return '7' + digits.slice(1);
  return digits.length === 9 ? '375' + digits : digits;
};
