import {useState} from 'react';
import {Alert, Box, Button, Chip, FormControlLabel, Stack, Switch, Table, TableBody, TableCell, TableHead, TableRow, TextField, Typography} from '@mui/material';
import {useNavigate, useSearchParams} from 'react-router-dom';
import {useGetOrderCustomersQuery} from '../orders/createOrder/createOrderApi';
import {communicationStyles, ICustomerCard} from '../../models/customer';
import useDebounce from '../../hooks/useDebounce';
import {MainDiv, PageHeader, PageSubtitle, PageTitle, PageTitleGroup, Surface} from '../../ui/commonStyled/commonStyled';
import {clearCreateOrderDraft} from '../orders/createOrder/createOrderDraft';
import Loader from '../../ui/loader/loader';
import CustomerDetailDialog, {customerDate, customerMoney} from './CustomerDetailDialog';
import CustomerEditDialog from './CustomerEditDialog';

export default function CustomersPage() {
    const [params] = useSearchParams();
    const navigate = useNavigate(); const [search, setSearch] = useState(''); const [page, setPage] = useState(1);
    const [selected, setSelected] = useState<number | null>(() => {const id = Number(params.get('customer')); return Number.isSafeInteger(id) && id > 0 ? id : null;}); const [creating, setCreating] = useState(false); const [attention, setAttention] = useState(false);
    const query = useDebounce(search.trim(), 300);
    const {currentData: customers, isFetching, isError, refetch} = useGetOrderCustomersQuery({search: query, page, pageSize: 20, attentionRequired: attention || undefined});
    function createOrder(customer?: ICustomerCard) {
        clearCreateOrderDraft(); navigate('/ordersManagement/createOrder', {state: customer ? {customer} : null});
    }
    return <MainDiv>
        <PageHeader><PageTitleGroup><PageTitle>Клиенты</PageTitle><PageSubtitle>Контакты, история заказов и важные договорённости команды.</PageSubtitle></PageTitleGroup>
            <Stack direction="row" gap={1}><Button variant="outlined" onClick={() => createOrder()}>Новый заказ</Button><Button variant="contained" onClick={() => setCreating(true)}>Добавить клиента</Button></Stack>
        </PageHeader>
        <Surface>
            <TextField fullWidth label="Поиск по имени, любому телефону или адресу" value={search} onChange={event => {setSearch(event.target.value); setPage(1);}}/>
            <Stack direction="row" justifyContent="space-between" alignItems="center" flexWrap="wrap" gap={1} sx={{my: 2}}>
                <Typography color="text.secondary">{customers ? `Найдено клиентов: ${customers.total}` : 'Загружаем клиентов…'}</Typography>
                <FormControlLabel control={<Switch checked={attention} onChange={event => {setAttention(event.target.checked); setPage(1);}}/>} label="Требуют внимания / открытые ситуации"/>
            </Stack>
            {isError && <Alert severity="error" action={<Button onClick={() => void refetch()}>Повторить</Button>}>Не удалось загрузить клиентов.</Alert>}
            {isFetching && <Loader/>}
            {customers && <>
                {customers.items.length === 0 ? <Box sx={{py: 4, textAlign: 'center'}}><Typography fontWeight={700}>Клиенты не найдены</Typography><Typography color="text.secondary">Измените поиск или добавьте новую карточку. Клиенты также добавляются при оформлении заказа.</Typography></Box> :
                    <Box sx={{overflowX: 'auto'}}><Table aria-label="База клиентов"><TableHead><TableRow>
                        <TableCell>Клиент</TableCell><TableCell>Контакты</TableCell><TableCell>Заказы за всё время</TableCell><TableCell>Последний заказ</TableCell><TableCell>Действия</TableCell>
                    </TableRow></TableHead><TableBody>{customers.items.map(customer => <TableRow key={customer.id} hover>
                        <TableCell><Button sx={{p: 0, textAlign: 'left', justifyContent: 'flex-start', fontWeight: 700}} onClick={() => setSelected(customer.id)}>{customer.name}</Button>
                            <Stack direction="row" gap={0.5} flexWrap="wrap" mt={1}>
                                {customer.communicationStyle && customer.communicationStyle !== 'unknown' && <Chip size="small" variant="outlined" label={communicationStyles[customer.communicationStyle]}/>}
                                {customer.attentionRequired && <Chip size="small" color="warning" label="Требует внимания"/>}
                                {!!customer.openIncidentCount && <Chip size="small" color="error" variant="outlined" label={`Ситуаций: ${customer.openIncidentCount}`}/>}
                            </Stack>
                            {customer.summary && <Typography variant="body2" color="text.secondary" sx={{mt: 1, maxWidth: 300}}>{customer.summary.length > 140 ? `${customer.summary.slice(0, 140)}…` : customer.summary}</Typography>}
                        </TableCell>
                        <TableCell><Typography>{customer.phone}</Typography>{(customer.phones?.length || 0) > 1 && <Typography variant="caption" color="text.secondary">Ещё номеров: {customer.phones!.length - 1}</Typography>}<Typography variant="body2" color="text.secondary">{customer.address}</Typography></TableCell>
                        <TableCell><Typography>{customer.orderCount}</Typography><Typography variant="body2" color="text.secondary">{customerMoney(customer.totalAmount)}</Typography></TableCell><TableCell>{customerDate(customer.lastOrderAt)}</TableCell>
                        <TableCell><Stack gap={1}><Button onClick={() => setSelected(customer.id)}>Карточка и история</Button><Button variant="outlined" onClick={() => createOrder(customer)}>Создать заказ</Button></Stack></TableCell>
                    </TableRow>)}</TableBody></Table></Box>}
                <Stack direction="row" alignItems="center" justifyContent="space-between" gap={2} mt={2}>
                    <Button disabled={page <= 1 || isFetching} onClick={() => setPage(value => value - 1)}>Назад</Button>
                    <Typography variant="body2">Страница {page} из {Math.max(1, Math.ceil(customers.total / 20))}</Typography>
                    <Button disabled={page * 20 >= customers.total || isFetching} onClick={() => setPage(value => value + 1)}>Далее</Button>
                </Stack>
            </>}
        </Surface>
        {selected && <CustomerDetailDialog key={selected} id={selected} onClose={() => setSelected(null)} onCreateOrder={createOrder}/>}
        {creating && <CustomerEditDialog onClose={() => setCreating(false)} onSaved={customer => {setCreating(false); setSelected(customer.id);}}/>}
    </MainDiv>;
}
