import {useRef, useState} from 'react';
import {Alert, Box, Button, Chip, CircularProgress, Dialog, DialogActions, DialogContent, DialogTitle, MenuItem, Paper, Stack, Tab, Tabs, TextField, Typography} from '@mui/material';
import {Link} from 'react-router-dom';
import {AddCustomerNoteInput, communicationStyles, ICustomerCard} from '../../models/customer';
import {useAddCustomerNoteMutation, useGetCustomerNotesQuery, useGetCustomerOrdersQuery, useGetCustomerQuery, useResolveCustomerNoteMutation} from '../orders/createOrder/createOrderApi';
import {getApiErrorMessage} from '../../api/errors';
import {newRequestId} from '../warehouse/receiptDraft';
import CustomerEditDialog from './CustomerEditDialog';

export const customerDate = (value?: string | null) => value ? new Date(value).toLocaleDateString('ru-RU') : '—';
export const customerMoney = (value: number) => value.toLocaleString('ru-RU', {minimumFractionDigits: 2, maximumFractionDigits: 2}) + ' BYN';
type Props = {id: number; onClose: () => void; onCreateOrder: (customer: ICustomerCard) => void};
function Pager({page, total, busy, onChange}: {page: number; total: number; busy?: boolean; onChange: (page: number) => void}) {
    return <Stack direction="row" justifyContent="space-between" alignItems="center" mt={2}>
        <Button disabled={page <= 1 || busy} onClick={() => onChange(page - 1)}>Назад</Button>
        <Typography variant="body2">Страница {page} из {Math.max(1, Math.ceil(total / 20))}</Typography>
        <Button disabled={page * 20 >= total || busy} onClick={() => onChange(page + 1)}>Далее</Button>
    </Stack>;
}
export default function CustomerDetailDialog({id, onClose, onCreateOrder}: Props) {
    const detail = useGetCustomerQuery(id); const customer = detail.currentData;
    const [tab, setTab] = useState(0); const [orderPage, setOrderPage] = useState(1); const [notePage, setNotePage] = useState(1);
    const orders = useGetCustomerOrdersQuery({id, page: orderPage}, {skip: tab !== 0});
    const notes = useGetCustomerNotesQuery({id, page: notePage}, {skip: tab !== 1});
    const [editing, setEditing] = useState(false); const [kind, setKind] = useState('note'); const [text, setText] = useState(''); const [orderId, setOrderId] = useState('');
    const [addNote, addState] = useAddCustomerNoteMutation(); const [resolve, resolveState] = useResolveCustomerNoteMutation();
    const [error, setError] = useState(''); const [saved, setSaved] = useState(false); const [pending, setPending] = useState(false);
    const retry = useRef<AddCustomerNoteInput | null>(null);
    async function saveNote() {
        setError(''); setSaved(false);
        const payload = retry.current ?? {customerId: id, requestId: newRequestId(), kind, text: text.trim(), orderId: orderId ? Number(orderId) : null};
        retry.current = payload; setPending(true);
        try {await addNote(payload).unwrap(); retry.current = null; setPending(false); setText(''); setOrderId(''); setNotePage(1); setSaved(true);}
        catch (failure) {
            const status = (failure as {status?: unknown}).status;
            if (typeof status === 'number' && status < 500) {retry.current = null; setPending(false);}
            setError(getApiErrorMessage(failure, 'Не удалось сохранить заметку. Повторите сохранение.'));
        }
    }
    async function closeIncident(noteId: number) {
        setError('');
        try {await resolve({customerId: id, noteId}).unwrap();}
        catch (failure) {setError(getApiErrorMessage(failure, 'Не удалось закрыть ситуацию.'));}
    }
    const history = orders.currentData;
    return <>
        <Dialog open onClose={addState.isLoading ? undefined : onClose} fullWidth maxWidth="lg" scroll="paper">
            <DialogTitle><Stack direction="row" justifyContent="space-between" gap={2} flexWrap="wrap"><span>{customer?.name || 'Карточка клиента'}</span>
                <Button disabled={!customer} onClick={() => setEditing(true)}>Редактировать карточку</Button></Stack></DialogTitle>
            <DialogContent>
                {detail.isLoading && <CircularProgress/>}
                {detail.isError && <Alert severity="error" action={<Button onClick={() => void detail.refetch()}>Повторить</Button>}>Не удалось загрузить клиента.</Alert>}
                {customer && <Stack spacing={2}>
                    <Stack direction="row" gap={1} flexWrap="wrap">
                        {customer.communicationStyle !== 'unknown' && <Chip variant="outlined" label={communicationStyles[customer.communicationStyle] || 'Стиль общения не указан'}/>}
                        {customer.attentionRequired && <Chip color="warning" label="Требует внимания"/>}
                        {customer.openIncidentCount > 0 && <Chip color="error" variant="outlined" label={`Открытых ситуаций: ${customer.openIncidentCount}`}/>}
                    </Stack>
                    <Box sx={{display: 'grid', gridTemplateColumns: {xs: '1fr 1fr', md: 'repeat(4, 1fr)'}, gap: 1}}>
                        {[[String(customer.orderCount), 'заказов за всё время'], [customerMoney(customer.totalAmount), 'сумма заказов'], [customerMoney(customer.orderCount ? customer.totalAmount / customer.orderCount : 0), 'средний заказ'], [customerDate(customer.lastOrderAt), 'последний заказ']].map(([value, label]) =>
                            <Paper key={label} variant="outlined" sx={{p: 2, minWidth: 0}}><Typography fontWeight={700}>{value}</Typography><Typography variant="caption" color="text.secondary">{label}</Typography></Paper>)}
                    </Box>
                    <Paper variant="outlined" sx={{p: 2}}><Stack spacing={1}>
                        {(customer.phones?.length ? customer.phones : [{phone: customer.phone, label: ''}]).map(phone => <Typography key={phone.phone}><a href={`tel:${phone.phone.replace(/[^+0-9]/g, '')}`}>{phone.phone}</a>{phone.label ? ` · ${phone.label}` : ''}</Typography>)}
                        {customer.address && <Typography color="text.secondary">{customer.address}</Typography>}
                        {customer.email && <Typography>{customer.email}</Typography>}
                        {(customer.taxNumber || customer.contract) && <Typography variant="body2">{[customer.taxNumber && `УНП: ${customer.taxNumber}`, customer.contract && `Договор: ${customer.contract}`].filter(Boolean).join(' · ')}</Typography>}
                        {customer.summary && <Alert severity={customer.attentionRequired ? 'warning' : 'info'}><Typography fontWeight={700}>Памятка для команды</Typography><Typography sx={{whiteSpace: 'pre-wrap', overflowWrap: 'anywhere'}}>{customer.summary}</Typography></Alert>}
                    </Stack></Paper>
                    <Tabs value={tab} variant="scrollable" scrollButtons="auto" allowScrollButtonsMobile onChange={(_, value) => {setTab(value); setError('');}} aria-label="Карточка клиента"><Tab label={`Все заказы (${customer.orderCount})`}/><Tab label="Заметки и ситуации"/><Tab label="Адреса и контакты"/></Tabs>
                    {tab === 0 && <Box>
                        <Typography variant="body2" color="text.secondary" sx={{mb: 1}}>История за всё время. В каждом заказе сохранены контакты на момент оформления.</Typography>
                        {orders.isFetching && <CircularProgress size={22}/>}
                        {orders.isError && <Alert severity="error" action={<Button onClick={() => void orders.refetch()}>Повторить</Button>}>История заказов недоступна.</Alert>}
                        {(history?.items || (orderPage === 1 ? customer.orders : [])).map(order => <Paper key={order.id} variant="outlined" sx={{p: 2, mb: 1}}>
                            <Stack direction="row" justifyContent="space-between" gap={1} flexWrap="wrap"><Typography fontWeight={700}><Link to={`/ordersManagement/${order.id}`}>Заказ №{order.id}</Link> · {customerDate(order.createdDate)}</Typography><Chip size="small" label={order.status}/></Stack>
                            <Typography sx={{mt: 1}}>{customerMoney(order.finalSum)}</Typography>
                            <Typography variant="body2" color="text.secondary">{order.name} · {order.phone} · {order.address}</Typography>
                            {order.comment && <Typography variant="body2" sx={{whiteSpace: 'pre-wrap', mt: 1}}>{order.comment}</Typography>}
                        </Paper>)}
                        {customer.orderCount === 0 && <Alert severity="info">У клиента пока нет заказов.</Alert>}
                        <Pager page={orderPage} total={history?.total ?? customer.orderCount} busy={orders.isFetching} onChange={setOrderPage}/>
                    </Box>}
                    {tab === 1 && <Stack spacing={2}>
                        <Paper variant="outlined" sx={{p: 2}}><Stack component="form" spacing={2} onSubmit={event => {event.preventDefault(); void saveNote();}}>
                            <Typography fontWeight={700}>Запись в журнал</Typography>
                            <Stack direction={{xs: 'column', sm: 'row'}} gap={2}>
                                <TextField select fullWidth label="Тип записи" value={kind} disabled={pending} onChange={event => setKind(event.target.value)}><MenuItem value="note">Заметка</MenuItem><MenuItem value="incident">Неприятная ситуация</MenuItem></TextField>
                                <TextField fullWidth label="Номер заказа, если относится к нему" value={orderId} disabled={pending} inputProps={{inputMode: 'numeric', pattern: '[0-9]*'}} onChange={event => setOrderId(event.target.value.replace(/\D/g, ''))}/>
                            </Stack>
                            <TextField required label="Текст заметки" multiline minRows={3} value={text} disabled={pending} inputProps={{maxLength: 4000}} onChange={event => {setText(event.target.value); setSaved(false);}}
                                helperText="Запишите факты, договорённости и что поможет коллеге. Автор и дата сохранятся автоматически."/>
                            {error && <Alert severity="error">{error}</Alert>}
                            {saved && <Alert severity="success">Заметка сохранена.</Alert>}
                            <Button type="submit" variant="contained" sx={{alignSelf: 'flex-start'}} disabled={!text.trim() || addState.isLoading}>{addState.isLoading ? 'Сохраняем…' : pending ? 'Повторить сохранение' : 'Добавить запись'}</Button>
                        </Stack></Paper>
                        {notes.isFetching && <CircularProgress size={22}/>}
                        {notes.isError && <Alert severity="error" action={<Button onClick={() => void notes.refetch()}>Повторить</Button>}>Не удалось загрузить журнал.</Alert>}
                        {notes.currentData?.items.map(note => <Paper key={note.id} variant="outlined" sx={{p: 2, borderColor: note.kind === 'incident' && !note.isResolved ? 'warning.main' : 'divider'}}>
                            <Stack direction="row" alignItems="center" gap={1} flexWrap="wrap"><Chip size="small" color={note.kind === 'incident' ? note.isResolved ? 'success' : 'warning' : 'default'} label={note.kind === 'incident' ? note.isResolved ? 'Ситуация решена' : 'Неприятная ситуация' : 'Заметка'}/>
                                <Typography variant="caption" color="text.secondary">{note.authorName} · {new Date(note.createdAt).toLocaleString('ru-RU')}</Typography></Stack>
                            <Typography sx={{whiteSpace: 'pre-wrap', overflowWrap: 'anywhere', mt: 1}}>{note.text}</Typography>
                            {note.orderId && <Button component={Link} to={`/ordersManagement/${note.orderId}`} size="small">Заказ №{note.orderId}</Button>}
                            {note.kind === 'incident' && !note.isResolved && <Button size="small" disabled={resolveState.isLoading} onClick={() => void closeIncident(note.id)}>Отметить решённой</Button>}
                            {note.resolvedAt && <Typography variant="caption" color="text.secondary">Закрыта {new Date(note.resolvedAt).toLocaleString('ru-RU')}</Typography>}
                        </Paper>)}
                        {notes.currentData?.total === 0 && <Typography color="text.secondary">Заметок пока нет.</Typography>}
                        <Pager page={notePage} total={notes.currentData?.total || 0} busy={notes.isFetching} onChange={setNotePage}/>
                    </Stack>}
                    {tab === 2 && <Stack spacing={1}><Typography fontWeight={700}>Адреса из истории заказов</Typography>
                        {customer.addresses.map(address => <Paper key={address} variant="outlined" sx={{p: 2}}>{address}</Paper>)}
                        {!customer.addresses.length && <Typography color="text.secondary">Адреса появятся после первого заказа.</Typography>}
                        <Typography variant="body2" color="text.secondary">Первый заказ: {customerDate(customer.firstOrderAt)}. Изменение карточки не переписывает контакты в прошлых заказах.</Typography>
                    </Stack>}
                </Stack>}
            </DialogContent>
            <DialogActions><Button onClick={onClose}>Закрыть</Button><Button variant="contained" disabled={!customer} onClick={() => customer && onCreateOrder(customer)}>Создать заказ</Button></DialogActions>
        </Dialog>
        {editing && customer && <CustomerEditDialog customer={customer} onClose={() => setEditing(false)} onSaved={() => setEditing(false)}/>}
    </>;
}
