import {StockLookup, ReceiveStock} from "./warehouseReceiptsApi";
export type ReceiptDraft = {requestId: string; lines: (StockLookup & {quantity: number})[]; comment: string; submitted: boolean};
export function positiveQuantity(value: string): number | null {
    const normalized = value.trim().replace(",", ".");
    if (!/^\d+(?:\.\d{1,6})?$/.test(normalized)) return null;
    const result = Number(normalized);
    return Number.isFinite(result) && result > 0 && result <= 1e12 ? result : null;
}
export const receiptPayload = (draft: ReceiptDraft): ReceiveStock => ({requestId: draft.requestId, comment: draft.comment,
    lines: draft.lines.map(line => ({gtin: line.gtin, quantity: line.quantity}))});
export function newRequestId(): string {
    const bytes = crypto.getRandomValues(new Uint8Array(16)); bytes[6] = (bytes[6] & 15) | 64; bytes[8] = (bytes[8] & 63) | 128;
    const hex = Array.from(bytes, byte => byte.toString(16).padStart(2, "0")).join("");
    return `${hex.slice(0,8)}-${hex.slice(8,12)}-${hex.slice(12,16)}-${hex.slice(16,20)}-${hex.slice(20)}`;
}
